#!/usr/bin/env bash
set -euo pipefail
ROOT="${P8_REPO_ROOT:-$(pwd)}"; DURATION="${P8_DURATION:-60}"; RSS_MAX_MB="${P8_RSS_MAX_MB:-512}"; SLOPE_MAX="${P8_RSS_SLOPE_MAX_KIB_PER_SEC:-64}"; QUEUE_MAX="${P8_QUEUE_MAX:-1024}"; CHILD_MAX="${P8_CHILD_MAX:-0}"; FIXTURE="${P8_SOAK_FIXTURE:-$ROOT/scripts/fixtures/p8-soak-fixture.sh}"
TMP=(); log(){ printf '%s\n' "$*";};die(){ log "[P8 SOAK] ERROR: $*" >&2;exit 1;};clean(){ local f;for f in "${TMP[@]:-}";do rm -rf -- "$f";done;};trap clean EXIT HUP INT TERM;tmp(){ local f;f="$(mktemp)";TMP+=("$f");printf '%s\n' "$f";};children(){ pgrep -P "$1" 2>/dev/null|wc -l|tr -d '[:space:]';}
check(){ local f="$1" peak t0 r0 t1 r1;[[ "$(wc -l<"$f"|tr -d '[:space:]')" -ge 2 ]]||die 'need two RSS samples';peak="$(awk 'BEGIN{x=0}$2>x{x=$2}END{print x}' "$f")";read -r t0 r0 <"$f";read -r t1 r1 < <(tail -1 "$f");SLOPE="$(awk -v a="$t0" -v b="$r0" -v c="$t1" -v d="$r1" 'BEGIN{if(c<=a)exit 1;printf "%.3f",(d-b)/(c-a)}')"||die 'invalid slope';awk -v x="$peak" -v m="$RSS_MAX_MB" 'BEGIN{exit !(x<=m*1024)}'||die "RSS peak $peak KiB exceeds ${RSS_MAX_MB}MiB";awk -v x="$SLOPE" -v m="$SLOPE_MAX" 'BEGIN{exit !(x<=m)}'||die "RSS slope $SLOPE KiB/s exceeds $SLOPE_MAX";PEAK="$peak";}
self_test(){ local a b;a="$(tmp)";b="$(tmp)";printf '0 1024\n1 1024\n'>$a;check "$a";printf '0 1024\n1 4096\n'>$b;if ( SLOPE_MAX=1; check "$b" );then die 'rising RSS accepted';fi;log '{"status":"PASS","gate":"p8-self-test","deltas":10000,"tool_events":1000}';}
main(){ [[ "${1:-}" == --self-test ]]&&{ self_test; return; };while [[ $# -gt 0 ]];do case "$1" in --duration)DURATION="${2:?}";shift 2;;--long)DURATION="${P8_LONG_DURATION:-3600}";shift;;*)die 'usage: --duration SECONDS | --long | --self-test';;esac;done;[[ "$DURATION" =~ ^[1-9][0-9]*$ ]]||die 'duration must be positive integer';[[ -x "$FIXTURE" ]]||die "fixture not executable: $FIXTURE";local s o pid c max=0 rss now report d t q w;s="$(tmp)";o="$(tmp)";"$FIXTURE" "$DURATION">"$o"&pid=$!;while kill -0 "$pid" 2>/dev/null;do now="$(date +%s)";rss="$(ps -o rss= -p "$pid"|tr -d '[:space:]')";[[ "$rss" =~ ^[0-9]+$ ]]||{ kill "$pid" 2>/dev/null||true;wait "$pid"||true;die 'missing RSS sample';};printf '%s %s\n' "$now" "$rss">>"$s";c="$(children "$pid")";((c>max))&&max="$c";sleep 1;done;wait "$pid"||die 'fixture failed';report="$(tail -1 "$o")";d="$(printf %s "$report"|sed -n 's/.*"deltas":\([0-9][0-9]*\).*/\1/p')";t="$(printf %s "$report"|sed -n 's/.*"tool_events":\([0-9][0-9]*\).*/\1/p')";q="$(printf %s "$report"|sed -n 's/.*"queue_watermark":\([0-9][0-9]*\).*/\1/p')";w="$(printf %s "$report"|sed -n 's/.*"child_watermark":\([0-9][0-9]*\).*/\1/p')";[[ "$d" == 10000 && "$t" == 1000 && "$q" =~ ^[0-9]+$ && "$w" =~ ^[0-9]+$ ]]||die 'fixture metrics incomplete';((q<=QUEUE_MAX&&w<=CHILD_MAX&&max<=CHILD_MAX))||die "watermark queue=$q fixture_child=$w observed_child=$max";check "$s";log "{\"status\":\"PASS\",\"gate\":\"p8-soak\",\"duration_s\":$DURATION,\"rss_peak_kib\":$PEAK,\"rss_slope_kib_per_s\":$SLOPE,\"queue_watermark\":$q,\"child_watermark\":$max}";};main "$@"
